<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getList, getPage, post, put } from '@/api/resources'
import { http, problemMessage } from '@/api/http'
import { useSessionStore } from '@/stores/session'
import ProductionHint from '@/components/ProductionHint.vue'
import type { IntegrationMessage, IntegrationPipeline } from '@/types/domain'
import { formatDate, formatNumber, integrationStatusLabel, integrationStatusType } from '@/utils/format'

interface Platform { id: string; name: string; enabled: boolean; forceFailure?: boolean }
const session = useSessionStore(); const isAdmin = () => session.hasAnyRole(['Administrator']); const platforms = ref<Platform[]>([]); const pipeline = ref<IntegrationPipeline>(); const messages = ref<IntegrationMessage[]>([]); const loading = ref(true); const refreshing = ref(false); const mutating = ref(false); const error = ref(''); const syncing = ref('')
let timer: number | undefined; let request: Promise<void> | undefined; let revision = 0; let disposed = false
async function load(): Promise<void> {
  if (disposed || mutating.value) return
  if (request) return request
  const currentRevision = revision; refreshing.value = true; error.value = ''
  request = (async () => {
    try { const [platformData, pipelineData, messageData] = await Promise.all([getList<Platform>('/integrations/platforms'), http.get<IntegrationPipeline>('/integrations/pipeline'), getPage<IntegrationMessage>('/integrations/messages')]); if (!disposed && currentRevision === revision) { platforms.value = platformData; pipeline.value = pipelineData.data; messages.value = messageData.items } }
    catch (e) { if (!disposed && currentRevision === revision) error.value = problemMessage(e) }
    finally { refreshing.value = false; loading.value = false }
  })()
  await request; request = undefined
}
async function mutate(action: () => Promise<unknown>, success: string): Promise<void> {
  if (disposed || mutating.value) return
  mutating.value = true; revision++ // Do not let a poll started before the mutation overwrite its result.
  try { await action(); if (!disposed) ElMessage.success(success) } catch (e) { if (!disposed) ElMessage.error(problemMessage(e)) }
  finally { await request; mutating.value = false; if (!disposed) await load() }
}
async function update(item: Platform): Promise<void> { const body = { enabled: item.enabled, forceFailure: item.forceFailure }; await mutate(() => put(`/integrations/platforms/${item.id}`, body), '模拟平台状态已更新。') }
async function sync(platform: Platform, kind: 'Assets' | 'VisitorCount' | 'VideoMetadata' | 'PublicCodes'): Promise<void> { if (mutating.value) return; syncing.value = `${platform.id}-${kind}`; try { await mutate(() => post('/integrations/sync', { platformId: platform.id, kind }), '本地模拟同步任务已生成，未发送至外部网络。') } finally { syncing.value = '' } }
async function retry(item: IntegrationMessage): Promise<void> { if (item.status !== 'Failed') return; await mutate(() => post(`/integrations/messages/${item.id}/retry`), '已请求本地重试，将按新代次重新发布。') }
onMounted(() => { void load(); timer = window.setInterval(() => { if (!document.hidden && !mutating.value) void load() }, 3000) })
onBeforeUnmount(() => { disposed = true; revision++; window.clearInterval(timer) })
</script>
<template><div class="page"><div class="page-heading"><div><h1>外部平台协同</h1><p>五类平台使用共享本地模拟适配器，仅保留业务映射与回执日志。</p></div><el-button @click="load">刷新日志</el-button></div><el-alert v-if="error" type="error" :title="error" :closable="false" /><section class="surface pipeline-panel"><div class="data-title">本地消息链路</div><p class="muted">业务消息先发布到本机 RabbitMQ 队列，再由本地模拟消费者生成回执；不接入任何官方平台，计数来自数据库记录，不代表 Broker 健康或队列深度。</p><div class="pipeline-chain"><span>业务事务 + Outbox</span><i>→</i><span>RabbitMQ 发布</span><i>→</i><span>本地模拟消费</span><i>→</i><span>回执 / 退避</span></div><div class="pipeline-stats"><article><span>待发布/退避</span><b>{{ formatNumber(pipeline?.pending) }}</b></article><article><span>已确认待消费</span><b>{{ formatNumber(pipeline?.published) }}</b></article><article><span>本地回执成功</span><b>{{ formatNumber(pipeline?.succeeded) }}</b></article><article><span>重试耗尽</span><b>{{ formatNumber(pipeline?.failed) }}</b></article></div><p class="muted">传输 {{ pipeline?.transport || '—' }} · 主队列 {{ pipeline?.queueName || '—' }} · 死信队列 {{ pipeline?.deadLetterQueueName || '—' }}</p></section><section class="platform-grid" v-loading="loading"><article v-for="platform in platforms" :key="platform.id" class="surface platform-card"><div><span>本地模拟适配器</span><h3>{{ platform.name }}</h3><p>{{ platform.enabled ? '已启用本地模拟回执' : '已停用，不会生成同步回执' }}</p></div><el-switch v-if="isAdmin()" :disabled="mutating" v-model="platform.enabled" active-text="模拟启用" inactive-text="已停用" @change="update(platform)" /><el-tag v-else :type="platform.enabled ? 'success' : 'info'">{{ platform.enabled ? '模拟启用' : '已停用' }}</el-tag><div v-if="isAdmin()" class="failure"><el-checkbox :disabled="mutating" v-model="platform.forceFailure" @change="update(platform)">注入模拟失败</el-checkbox></div><div class="sync-actions"><el-button size="small" :disabled="mutating || !platform.enabled" :loading="syncing === `${platform.id}-Assets`" @click="sync(platform, 'Assets')">资产</el-button><el-button size="small" :disabled="mutating || !platform.enabled" :loading="syncing === `${platform.id}-VisitorCount`" @click="sync(platform, 'VisitorCount')">客流</el-button><el-button size="small" :disabled="mutating || !platform.enabled" :loading="syncing === `${platform.id}-VideoMetadata`" @click="sync(platform, 'VideoMetadata')">视频元数据</el-button><el-button size="small" :disabled="mutating || !platform.enabled" :loading="syncing === `${platform.id}-PublicCodes`" @click="sync(platform, 'PublicCodes')">公开物码</el-button></div></article><el-empty v-if="!loading && !platforms.length" description="暂无平台配置" /></section><section class="surface table-panel"><div class="data-title">模拟同步消息</div><p class="muted">成功只表示本地模拟消费者生成回执，未发送外部网络；Published 只表示队列已确认、等待本地消费，不是业务成功。失败按服务端退避规则自动重试，仅重试耗尽可人工重试。</p><el-table :data="messages" row-key="id" empty-text="暂无同步消息"><el-table-column type="expand"><template #default="scope"><div class="attempt-logs"><el-table :data="scope.row.attemptLogs ?? []" size="small" empty-text="暂无阶段日志"><el-table-column label="阶段" width="90"><template #default="log">{{ log.row.stage === 'Publish' ? '发布' : '消费' }}</template></el-table-column><el-table-column prop="generation" label="代次" width="70" /><el-table-column prop="attempt" label="尝试" width="70" /><el-table-column label="结果" width="90"><template #default="log"><el-tag size="small" :type="log.row.success ? 'success' : 'danger'">{{ log.row.success ? '成功' : '失败' }}</el-tag></template></el-table-column><el-table-column label="时间" width="170"><template #default="log">{{ formatDate(log.row.attemptedAt) }}</template></el-table-column><el-table-column prop="message" label="说明" min-width="200" /></el-table></div></template></el-table-column><el-table-column label="状态" width="140"><template #default="scope"><el-tag size="small" effect="light" :type="integrationStatusType(scope.row.status)">{{ integrationStatusLabel[scope.row.status] ?? scope.row.status }}</el-tag></template></el-table-column><el-table-column prop="platformName" label="目标平台" min-width="160" /><el-table-column prop="kind" label="业务类型" width="130" /><el-table-column label="消息 ID" min-width="260"><template #default="scope"><span :data-message-id="scope.row.id">{{ scope.row.id }}</span></template></el-table-column><el-table-column label="代次" width="80"><template #default="scope">{{ scope.row.generation ?? 0 }}</template></el-table-column><el-table-column label="发布/消费" width="110"><template #default="scope">{{ scope.row.publishAttempts ?? 0 }} / {{ scope.row.attempts ?? 0 }}</template></el-table-column><el-table-column label="发布时间" width="170"><template #default="scope">{{ formatDate(scope.row.publishedAt) }}</template></el-table-column><el-table-column label="消费时间" width="170"><template #default="scope">{{ formatDate(scope.row.consumedAt) }}</template></el-table-column><el-table-column label="回执错误" min-width="200"><template #default="scope">{{ scope.row.lastError || scope.row.detail || '—' }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="scope"><el-button v-if="scope.row.status === 'Failed'" link type="primary" :disabled="mutating" @click="retry(scope.row)">人工重试</el-button></template></el-table-column></el-table></section><ProductionHint topic="platforms" /></div></template>
<style scoped>.pipeline-panel { margin-bottom:18px; padding:18px; }.pipeline-panel .data-title { margin-bottom:6px; }.pipeline-chain { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:14px 0; font-size:13px; }.pipeline-chain span { padding:6px 11px; border-radius:99px; color:#3c6159; background:#eef5f2; }.pipeline-chain i { color:#8aa39c; font-style:normal; }.pipeline-stats { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:12px; margin:14px 0; }.pipeline-stats article { padding:12px; border-radius:9px; background:#f4f8f6; }.pipeline-stats span { display:block; color:#758680; font-size:11px; }.pipeline-stats b { display:block; margin-top:5px; color:#2b5b50; font-size:22px; }.platform-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }.platform-card { padding:18px; }.platform-card > div:first-child { min-height:82px; }.platform-card span { color:#789087; font-size:11px; }.platform-card h3 { margin:7px 0; color:#2b5147; font-size:16px; }.platform-card p { margin:0; color:#70817b; font-size:12px; }.failure { margin:14px 0; }.sync-actions { display:flex; flex-wrap:wrap; gap:6px; }.table-panel { margin-top:18px; padding:18px; }.table-panel .data-title { margin-bottom:4px; }.attempt-logs { padding:6px 20px 14px; }</style>
